```java
static public I18NBundle createBundle (FileHandle baseFileHandle, Locale locale, String encoding) {
    if (baseFileHandle == null) throw new IllegalArgumentException("baseFileHandle is null");
    if (locale == null) locale = Locale.getDefault();
    if (encoding == null) encoding = "UTF-8";

    I18NBundle bundle = null;
    I18NBundle parentBundle = null;
    Locale candidateLocale = null;

    String baseFilePath = baseFileHandle.path();
    // remove the extension if present
    int dotIndex = baseFilePath.lastIndexOf('.');
    String rootPath = (dotIndex == -1) ? baseFilePath : baseFilePath.substring(0, dotIndex);

    // Build candidate locales from most specific to least, ending with the root bundle
    while (true) {
        // get next candidate locale
        ...
        // candidate file name
        String filePath;
        if (candidateLocale == null) {
